content='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Components of 2x2 blocks; recolor blocks participating in an
    # orthogonally connected chain of exactly three blocks (demo pattern).
    blocks = []
    for r in range(h-1):
        for c in range(w-1):
            if all(grid[y][x] == 2 for y in (r,r+1) for x in (c,c+1)):
                blocks.append((r,c))
    # Merge overlapping/touching blocks by 2x2 positions at manhattan distance 2.
    adj = {b: [] for b in blocks}
    for a in blocks:
        for b in blocks:
            if a != b and abs(a[0]-b[0]) + abs(a[1]-b[1]) == 2:
                adj[a].append(b)
    seen=set()
    for b in blocks:
        if b in seen: continue
        stack=[b]; comp=[]; seen.add(b)
        while stack:
            q=stack.pop(); comp.append(q)
            for z in adj[q]:
                if z not in seen: seen.add(z); stack.append(z)
        if len(comp)==3:
            for r,c in comp:
                for y in (r,r+1):
                    for x in (c,c+1): out[y][x]=8
    return out
'''
