 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Identify 2x2 tiles. Change the ones in the longest diagonal chain.
    tiles = []
    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[y][x] == 2 for y in (r, r + 1) for x in (c, c + 1)):
                tiles.append((r, c))
    adj = {p: [] for p in tiles}
    for r, c in tiles:
        for dr, dc in ((1, 1), (1, -1)):
            q = (r + dr, c + dc)
            if q in adj:
                adj[(r, c)].append(q)
                adj[q].append((r, c))
    seen = set()
    components = []
    for p in tiles:
        if p in seen:
            continue
        stack, comp = [p], []
        seen.add(p)
        while stack:
            q = stack.pop()
            comp.append(q)
            for z in adj[q]:
                if z not in seen:
                    seen.add(z)
                    stack.append(z)
        components.append(comp)
    if components:
        largest = max(components, key=len)
        if len(largest) > 1:
            for r, c in largest:
                for y in (r, r + 1):
                    for x in (c, c + 1):
                        out[y][x] = 8
    return out
