 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Detect vertically connected 2x3 rectangles and mark those, along with
    # the lower-left 2x2 endpoint of the same diagonal arrangement.
    objects = []
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 2 and (yy,xx) not in seen:
                        seen.add((yy,xx))
                        stack.append((yy,xx))
            objects.append(comp)
    for comp in objects:
        ys = [y for y, x in comp]
        xs = [x for y, x in comp]
        top, left = min(ys), min(xs)
        if len(comp) == 6 or (len(comp) == 4 and top == h - 2 and left == 0):
            for y, x in comp:
                out[y][x] = 8
    return out
