    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    blocks = []
    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[y][x] == 2 for y in (r, r + 1) for x in (c, c + 1)):
                blocks.append((r, c))
    # Find the longest descending diagonal sequence of 2x2 objects.
    blocks.sort()
    lengths = []
    paths = []
    for i, (r, c) in enumerate(blocks):
        best_path = [i]
        for j, (pr, pc) in enumerate(blocks[:i]):
            candidate = paths[j] + [i]
            if pr < r and pc > c and len(candidate) > len(best_path):
                best_path = candidate
        paths.append(best_path)
        lengths.append(len(best_path))
    if paths:
        chosen = max(range(len(paths)), key=lambda i: lengths[i])
        for i in paths[chosen]:
            r, c = blocks[i]
            for y in (r, r + 1):
                for x in (c, c + 1):
                    out[y][x] = 8
    return out
